    ok = set()
    for i in range(m):
        ok.add((data[3 + 2 * i], data[4 + 2 * i]))
    n, k = len(s), len(sub)
    for start in range(n - k + 1):
        j = 0
        while j < k:
            a, b = sub[j], s[start + j]
