pairs = [(data[3 + 2 * i], data[4 + 2 * i]) for i in range(m)]
found = False
for start in range(len(s) - len(sub) + 1):
    good = True
    for j in range(len(sub)):
        if sub[j] == s[start + j]:
            continue
        hit = False
        for old, new in pairs:
            if old == sub[j] and new == s[start + j]:
                hit = True
        if not hit:
            good = False
            break
    if good:
        found = True
        break
print('true' if found else 'false')

